import { Schema } from "effect";

/**
 * ISO calendar date used for effective-period boundaries.
 *
 * The value is branded after validating the `YYYY-MM-DD` shape and checking
 * that JavaScript can parse it as a real date. Effective periods use calendar
 * dates rather than tax-year labels so mid-year official changes can be
 * represented precisely.
 *
 * @since 0.1.0
 */
export const IsoDate = Schema.String.pipe(Schema.brand("taxkit/IsoDate"));

/**
 * ISO calendar date used for effective-period boundaries.
 *
 * @since 0.1.0
 */
export type IsoDate = typeof IsoDate.Type;

/**
 * Half-open date interval `[from, toExclusive)`.
 *
 * `toExclusive` may be absent only for an open-ended official source.
 *
 * @since 0.1.0
 */
export const DateInterval = Schema.Struct({
  from: IsoDate,
  toExclusive: Schema.optional(IsoDate),
});

/**
 * Half-open date interval `[from, toExclusive)`.
 *
 * @since 0.1.0
 */
export type DateInterval = typeof DateInterval.Type;

const isoDatePattern = /^\d{4}-\d{2}-\d{2}$/u;

const assertIsoDate = (value: string): void => {
  if (!isoDatePattern.test(value)) {
    throw new Error(`taxkit/core: expected ISO date YYYY-MM-DD, got ${value}`);
  }

  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  if (Number.isNaN(timestamp)) {
    throw new TypeError(`taxkit/core: invalid ISO date ${value}`);
  }
};

/**
 * Brands a validated ISO calendar date.
 *
 * @since 0.1.0
 */
export const isoDate = (value: string): IsoDate => {
  assertIsoDate(value);
  return IsoDate.make(value);
};

const optionalIsoDate = (
  value: string | IsoDate | undefined
): IsoDate | undefined => (typeof value === "string" ? isoDate(value) : value);

/**
 * Builds a validated half-open date interval.
 *
 * @since 0.1.0
 */
export const dateInterval = (args: {
  readonly from: string | IsoDate;
  readonly toExclusive?: string | IsoDate;
}): DateInterval => {
  const from = typeof args.from === "string" ? isoDate(args.from) : args.from;
  const toExclusive = optionalIsoDate(args.toExclusive);

  if (toExclusive !== undefined && String(from) >= String(toExclusive)) {
    throw new Error(
      `taxkit/core: expected interval start ${from} before end ${toExclusive}`
    );
  }

  return DateInterval.make(
    toExclusive === undefined ? { from } : { from, toExclusive }
  );
};

/**
 * Returns whether two half-open date intervals overlap.
 *
 * @since 0.1.0
 */
export const dateIntervalsOverlap = (
  left: DateInterval,
  right: DateInterval
): boolean =>
  String(left.from) < String(right.toExclusive ?? "9999-12-31") &&
  String(right.from) < String(left.toExclusive ?? "9999-12-31");

/**
 * Converts an Australian tax year label such as `2025-26` to its date
 * interval: `2025-07-01` through, but not including, `2026-07-01`.
 *
 * @since 0.1.0
 */
export const australianTaxYearInterval = (year: string): DateInterval => {
  const startYear = Number.parseInt(year.slice(0, 4), 10);
  if (!Number.isInteger(startYear)) {
    throw new TypeError(`taxkit/core: invalid Australian tax year ${year}`);
  }

  return dateInterval({
    from: `${startYear}-07-01`,
    toExclusive: `${startYear + 1}-07-01`,
  });
};
import { Money, aud } from "@taxkit/core/primitives";
import { TraceNode } from "@taxkit/core/trace";
import { Effect, Layer, Schema } from "effect";

import {
  AnnualTaxableIncome,
  AnnualTaxableIncomeFact,
} from "../facts/income.js";
import { AnnualTaxLedger, AnnualTaxLedgerFact } from "../facts/ledger.js";

/**
 * Annual Australian income tax report for one taxable-income scenario.
 *
 * `rawLiability` is the ledger total before flooring. `liability` is floored
 * at zero so offsets cannot produce a negative payable amount.
 *
 * @since 0.1.0
 */
export class AnnualTaxReport extends Schema.TaggedClass<AnnualTaxReport>()(
  "AnnualTaxReport",
  {
    ledger: AnnualTaxLedger,
    liability: Money,
    rawLiability: Money,
    rulePackVersion: Schema.String,
    taxableIncome: Money,
    trace: TraceNode,
  }
) {}

/**
 * Calculates annual income tax from the supplied taxable income and derived
 * annual tax ledger.
 *
 * @since 0.1.0
 */
export const CalculateAnnualTax = Effect.gen(function* () {
  const income = yield* AnnualTaxableIncomeFact;
  const ledger = yield* AnnualTaxLedgerFact;

  const { rawLiability } = ledger;
  const liability = rawLiability.cents < 0 ? aud(0) : rawLiability;

  return new AnnualTaxReport({
    ledger,
    liability,
    rawLiability,
    rulePackVersion: "rules-au-income-tax/0.0.0",
    taxableIncome: income.income,
    trace: ledger.trace,
  });
});

/**
 * Input schema for the annual-tax scenario helper.
 *
 * @since 0.1.0
 */
export const AnnualTaxScenarioInputSchema = Schema.Struct({
  taxableIncome: Money,
});

/**
 * Input type for the annual-tax scenario helper.
 *
 * @since 0.1.0
 */
export type AnnualTaxScenarioInput = typeof AnnualTaxScenarioInputSchema.Type;

/**
 * Builds the typed scenario layer for annual taxable income.
 *
 * Use this after an owning boundary has decoded `AnnualTaxScenarioInput`.
 *
 * @since 0.1.0
 */
export const AnnualTaxScenarioLiveFromInput = (input: AnnualTaxScenarioInput) =>
  Layer.succeed(AnnualTaxableIncomeFact)(
    new AnnualTaxableIncome({ income: input.taxableIncome })
  );
import { Money } from "@taxkit/core/primitives";
import { TraceNode } from "@taxkit/core/trace";
import { Effect, Layer, Schema } from "effect";

import {
  GrossPay,
  GrossPayFact,
  NetPayFact,
  PayPeriod,
  TaxablePayFact,
  TaxFreeThresholdClaimed,
  TaxFreeThresholdClaimedFact,
} from "../facts/pay.js";
import {
  PayWithholdingsLedger,
  PayWithholdingsLedgerFact,
} from "../facts/withholdings.js";

/**
 * Take-home pay report for one Australian pay-period scenario.
 *
 * The report preserves gross pay, taxable pay, the withholding ledger,
 * final net pay, and the trace rooted at the net-pay rule.
 *
 * @since 0.1.0
 */
export class TakeHomePayReport extends Schema.TaggedClass<TakeHomePayReport>()(
  "TakeHomePayReport",
  {
    grossPay: Money,
    netPay: Money,
    period: PayPeriod,
    rulePackVersion: Schema.String,
    taxablePay: Money,
    trace: TraceNode,
    withholdings: PayWithholdingsLedger,
    withholdingsTotal: Money,
  }
) {}

/**
 * Calculates the take-home pay report from the facts supplied by a rule pack.
 *
 * Requires the derived `TaxablePayFact`, `PayWithholdingsLedgerFact`, and
 * `NetPayFact`; scenario input is supplied separately by `TakeHomeScenarioLive`.
 *
 * @since 0.1.0
 */
export const CalculateTakeHomePay = Effect.gen(function* () {
  const gross = yield* GrossPayFact;
  const taxable = yield* TaxablePayFact;
  const ledger = yield* PayWithholdingsLedgerFact;
  const net = yield* NetPayFact;

  return new TakeHomePayReport({
    grossPay: gross.amount,
    netPay: net.amount,
    period: gross.period,
    rulePackVersion: "rules-au-pay/0.0.0",
    taxablePay: taxable.amount,
    trace: net.trace,
    withholdings: ledger,
    withholdingsTotal: ledger.total,
  });
});

/**
 * Calculates the pay-period withholding ledger from the standard pay scenario.
 *
 * This is the withholding-specific calculator entrypoint over the same
 * scenario and PAYG ledger facts used by take-home pay.
 *
 * @since 0.1.0
 */
export const CalculatePayWithholdings = PayWithholdingsLedgerFact;

/**
 * Input schema for the standard take-home-pay scenario helper.
 *
 * @since 0.1.0
 */
export const TakeHomeScenarioInputSchema = Schema.Struct({
  grossPay: GrossPay,
  taxFreeThresholdClaimed: Schema.Boolean,
});

/**
 * Input type for the standard take-home-pay scenario helper.
 *
 * @since 0.1.0
 */
export type TakeHomeScenarioInput = typeof TakeHomeScenarioInputSchema.Type;

/**
 * Builds the typed scenario layer for gross pay and tax-free-threshold status.
 *
 * Use this after an owning boundary has decoded `TakeHomeScenarioInput`.
 *
 * @since 0.1.0
 */
export const TakeHomeScenarioLiveFromInput = (input: TakeHomeScenarioInput) =>
  Layer.mergeAll(
    Layer.succeed(GrossPayFact)(input.grossPay),
    Layer.succeed(TaxFreeThresholdClaimedFact)(
      new TaxFreeThresholdClaimed({
        value: input.taxFreeThresholdClaimed,
      })
    )
  );
